{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C01", "C02", "C10", "C24", "C29", "C13", "C15"],
  "contradictory_card_ids": ["C136"],
  "prediction_basis_card_ids": ["C01", "C02", "C10", "C24", "C29", "C13", "C15"],
  "claims": [
    {
      "claim": "Fenspiride, a spiro piperidine ether/amine, had absolute oral bioavailability of 90% in healthy volunteers, supporting F >= 20% for the query's spiro piperidine-tetrahydrofuran scaffold.",
      "card_ids": ["C01", "C02"]
    },
    {
      "claim": "PF-592379, a small basic amine ether, had measured oral bioavailability of 28% in rats and 61-87% in dogs, with a predicted human value >60%, all above the 20% threshold.",
      "card_ids": ["C10", "C24", "C29", "C39", "C49", "C50", "C52", "C56"]
    },
    {
      "claim": "Nicotine-d2, a small basic N-methyl amine, had 44% oral bioavailability in humans, supporting high F for the similarly small basic amine query.",
      "card_ids": ["C13"]
    },
    {
      "claim": "Meperidine, an N-methyl piperidine with measurable CYP-mediated hepatic clearance, has a normal oral bioavailability of about 0.48, so hepatic metabolism of a basic N-methyl piperidine does not by itself imply F < 20%.",
      "card_ids": ["C15", "C225", "C238"]
    },
    {
      "claim": "Naloxone illustrates that high absorption can coexist with low F (Fa=90%, F=2%) and has high hepatocyte intrinsic clearance, but the query lacks naloxone's phenol/HBD and glucuronidation site, limiting transferability.",
      "card_ids": ["C136", "C215"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C215", "C225", "C226", "C238", "C211"]
    }
  ],
  "evidence_gaps": [
    "No direct measured oral bioavailability for the query molecule.",
    "No L6 record for the query or a close structural analog; L6 records are for other basic amines/opioids and are not query-specific.",
    "First-pass metabolism of the query is unmeasured; the tertiary amine and exocyclic alkene are potential liabilities, but no quantitative hepatic extraction data exist for the query.",
    "High ionization at pH 7.4 (basic pKa 9.58, logD -0.37) may reduce passive permeability, but no experimental permeability for the query is available.",
    "L6 hepatic clearance records are in vitro/ex vivo and do not directly measure oral bioavailability; transferability to the query is limited by structural differences.",
    "Cirrhosis-condition high-F records are not transferable to a healthy-condition query."
  ],
  "decision_summary": "Predicted high remains supported by fenspiride (90% human), PF-592379 (28% rat, 61-87% dog, >60% predicted human), and nicotine-d2 (44% human). L6 hepatic clearance records show that basic N-methyl amines can undergo CYP-mediated metabolism, but meperidine with a similar N-methyl piperidine has F ~0.48 and no query-specific low-F evidence was added; therefore the decision is kept at high with moderate confidence."
}

